.adm-tc--amber .adm-tc-btn:hover { box-shadow: 0 6px 14px rgba(217, 119, 6, .28); }

@media (max-width: 700px) {
  .adm-tc-stats { grid-template-columns: 1fr 1fr; }
  .adm-tc-stat:last-child { grid-column: 1 / -1; }
